var fizzBuzz = function(n) {
    const result = [];

    for (let i = 1; i <= n; i++) {
        const divisibleBy3 = i % 3 === 0;
        const divisibleBy5 = i % 5 === 0;

        if (divisibleBy3 && divisibleBy5) {
            result.push("FizzBuzz");
        } else if (divisibleBy3) {
            result.push("Fizz");
        } else if (divisibleBy5) {
            result.push("Buzz");
        } else {
            result.push(String(i));
        }
    }

    return result;
};
